refsection.programlisting:
F = gf_create_field(2, 4);
c = gf_divide(F, [0 1 0 0], [1 1 0 0])   // alpha / alpha^4 = alpha^12 = [1 1 1 1]
gf_to_exponential(F, c)                  // 12

// Inversos de los elementos no nulos de GF(7)
P = gf_create_field(7, 1);
gf_divide(P, 1, 1:6)                     // [1 4 5 2 3 6]

try
    gf_divide(F, [0 1 0 0], [0 0 0 0]);
catch
    disp(lasterror())                    // gf_divide: Division by zero.
end
